function renderTeacherTabs(){if(!data)return;if(activeTeacher!=='__final__'&&!data.teachers.some(t=>t.id===activeTeacher))activeTeacher=data.teachers[0]?.id||'';const root=$('#teacher-tabs');root.innerHTML=data.teachers.map(t=>{const items=data.assignments.filter(a=>a.teacher===t.id),complete=items.length&&items.every(a=>['previous','current','notebooks','cleanliness','feedback','suggestions'].every(k=>a[k]!==''&&a[k]!=null));return '<button type="button" role="tab" tabindex="'+(t.id===activeTeacher?'0':'-1')+'" aria-selected="'+(t.id===activeTeacher)+'" data-teacher="'+t.id+'"><span>'+esc(t.name||'New Teacher')+'</span><small>'+items.length+' subjects · '+(complete?'Complete':'In progress')+'</small></button>';}).join('')+'<button type="button" role="tab" class="final-report-tab" tabindex="'+(activeTeacher==='__final__'?'0':'-1')+'" aria-selected="'+(activeTeacher==='__final__')+'" data-teacher="__final__"><span>Final Report</span><small>Save · Preview · Export</small></button>';root.querySelectorAll('button').forEach(b=>b.onclick=()=>{activeTeacher=b.dataset.teacher;renderTeacherTabs();assignments();const name=data.teachers.find(t=>t.id===activeTeacher)?.name||'Teacher';notice(activeTeacher==='__final__'?'Final Report workspace opened':name+' workspace opened');});root.onkeydown=e=>{if(!['ArrowRight','ArrowLeft','Home','End'].includes(e.key))return;e.preventDefault();const buttons=[...root.querySelectorAll('button')],i=buttons.findIndex(b=>b.dataset.teacher===activeTeacher),n=e.key==='Home'?0:e.key==='End'?buttons.length-1:(i+(e.key==='ArrowRight'?1:-1)+buttons.length)%buttons.length;if(buttons[n]){activeTeacher=buttons[n].dataset.teacher;renderTeacherTabs();assignments();$('#teacher-tabs [aria-selected="true"]')?.focus();}};$('#active-teacher-name').textContent=activeTeacher==='__final__'?'Final Report':data.teachers.find(t=>t.id===activeTeacher)?.name||'Select a teacher';}
function subjectTaken(c){const matches=a=>Number(a.grade)===Number(c.grade)&&(String(a.subject_id)===String(c.id)||String(a.name||'').trim().toLocaleLowerCase()===String(c.name||'').trim().toLocaleLowerCase());return data.assignments.some(matches)||(remoteSnapshot?.assignments||[]).some(a=>a.teacher!==activeTeacher&&matches(a));}
